-- Third Indonesian pass: the `domain` label on each project, the one field the
-- earlier passes missed (it shows in the register table's DOMAIN column).
-- "Intelijen eksekutif" reads as an espionage agency in Indonesian, not
-- analytics; "di saku" is literal where "dalam genggaman" is the idiom.
INSERT OR REPLACE INTO content (key, value, updated_at) VALUES ('projects', '[{"id":"exec","pdf":"/porto/executive-dashboard.pdf","dom":"intel","y":59,"live":true,"year":"2025","ongoing":true,"name":"Executive Dashboard","runtime":["laravel@11.36.1","php@8.2.24","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Executive intelligence","id":"Analitik eksekutif"},"sum":{"en":"A single screen the ministry''s leadership opens to see the whole state-owned enterprise portfolio: every parent company, each entity across the groups, operational status, and the ownership structure underneath each one.","id":"Satu layar yang dibuka pimpinan kementerian untuk melihat seluruh portofolio BUMN: seluruh perusahaan induk, tiap entitas grup, status operasional, dan struktur kepemilikan di bawah masing-masing."},"hi":{"en":["Rolled every group entity into one live counter set without slowing the first paint.","Drew the ownership tree as an interactive org chart — parent, subsidiary, affiliate, down several levels.","Per-company drill-down: profile, group structure, subsidiaries, board of directors and commissioners.","Aggregations pushed into PostgreSQL views so the dashboard reads instead of computes."],"id":["Menggabungkan seluruh entitas grup menjadi satu set counter live tanpa memperlambat pemuatan pertama.","Menggambar pohon kepemilikan sebagai org chart interaktif — induk, anak, afiliasi, sampai beberapa tingkat.","Drill-down per perusahaan: profil, struktur grup, anak perusahaan, direksi dan komisaris.","Agregasi didorong ke PostgreSQL view supaya dashboard membaca, bukan menghitung."]},"screens":{"en":["Executive dashboard","BUMN data dashboard","Company profile","Group structure","Subsidiaries & affiliates","Board of directors"],"id":["Dashboard eksekutif","Dashboard data BUMN","Profil perusahaan","Struktur grup","Anak & afiliasi","Dewan direksi"]},"sketch":"donut"},{"id":"egrc","pdf":"/porto/egrc.pdf","dom":"gov","y":140,"live":true,"year":"2023","ongoing":true,"name":"EGRC","runtime":["laravel@9.52.16","php@8.2.3","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Governance, risk & compliance","id":"Tata kelola, risiko & kepatuhan"},"sum":{"en":"Enterprise Governance Risk Compliance — where every state-owned enterprise files its governance reports (internal audit, GCG, audit-board findings, board reports) and the ministry tracks what is still outstanding.","id":"Enterprise Governance Risk Compliance — tempat setiap BUMN menyerahkan laporan tata kelolanya (audit internal, GCG, temuan BPK, laporan direksi) dan kementerian memantau apa yang masih tertunggak."},"hi":{"en":["Submission pipeline with per-document status: draft, filed, verified, returned.","Filters by year, period and company so a reviewer reaches one filing in three clicks.","Sits behind Satu BUMN, the shared portal that also fronts Korespondensi and SiLaba.","Role-scoped access — ministry reviewers and enterprise submitters see different halves."],"id":["Alur pengajuan dengan status per dokumen: draft, terkirim, terverifikasi, dikembalikan.","Filter tahun, periode, dan perusahaan supaya verifikator sampai ke satu berkas dalam tiga klik.","Berada di balik Satu BUMN, portal bersama yang juga menaungi Korespondensi dan SiLaba.","Akses berbasis peran — verifikator kementerian dan pengirim BUMN melihat sisi berbeda."]},"screens":{"en":["Satu BUMN portal","Submission register","Verification queue","Report attachments"],"id":["Portal Satu BUMN","Daftar pengajuan","Antrean verifikasi","Lampiran laporan"]},"sketch":"portal"},{"id":"koresp","pdf":"/porto/korespondensi.pdf","dom":"gov","y":192,"live":true,"year":"2023","ongoing":true,"name":"Korespondensi","runtime":["laravel@9.52.16","php@8.2.3","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Official correspondence","id":"Korespondensi resmi"},"sum":{"en":"Dispatch and receipt of official letters between the ministry and every state-owned enterprise. Every letter is traceable from draft to receipt.","id":"Pengiriman dan penerimaan surat dinas antara kementerian dan seluruh BUMN. Tiap surat bisa ditelusuri dari draf sampai diterima."},"hi":{"en":["Two dashboards, two audiences — the ministry''s view and each enterprise''s view of the same ledger.","Quarterly and monthly volume trends, plus letter status split (draft, sent, received, disposed).","Per-enterprise breakdown so a slow responder is visible without asking anyone.","Charts fed by PostgreSQL aggregate views, cached per quarter."],"id":["Dua dashboard, dua audiens — sudut pandang kementerian dan tiap BUMN atas catatan yang sama.","Tren volume triwulanan dan bulanan, plus pembagian status surat (draf, terkirim, diterima, disposisi).","Rincian per BUMN sehingga yang lambat merespons terlihat tanpa perlu ditanya.","Grafik disuplai view agregat PostgreSQL, di-cache per triwulan."]},"screens":{"en":["Ministry dashboard","Enterprise dashboard","Outgoing register","Incoming register"],"id":["Dashboard kementerian","Dashboard BUMN","Register surat keluar","Register surat masuk"]},"sketch":"line"},{"id":"silaba","pdf":"/porto/silaba.pdf","dom":"gov","y":244,"live":true,"year":"2023","ongoing":true,"name":"SiLaba","runtime":["laravel@9.52.16","php@8.2.3","postgresql"],"org":"Kementerian BUMN","role":{"en":"Full-stack developer","id":"Full-stack developer"},"domain":{"en":"Periodic reporting","id":"Pelaporan berkala"},"sum":{"en":"Sistem Informasi Laporan Berkala. Enterprises upload their periodic filings — financial statements, management reports, cover letters — and ministry staff verify each one against the period it belongs to.","id":"Sistem Informasi Laporan Berkala. BUMN mengunggah laporan berkalanya — laporan keuangan, laporan manajemen, surat pengantar — dan staf kementerian memverifikasi tiap berkas sesuai periodenya."},"hi":{"en":["Report register and a separate verification queue, so filing and reviewing never collide.","Per-document status pills and an audit log of every status change.","Attachment handling for multi-file filings with a cover letter and supporting documents.","Search across company, year and quarter."],"id":["Register laporan dan antrean verifikasi terpisah, supaya pengiriman dan peninjauan tidak bertabrakan.","Label status per dokumen dan log audit untuk tiap perubahan status.","Penanganan lampiran untuk berkas multi-file dengan surat pengantar dan dokumen pendukung.","Pencarian lintas perusahaan, tahun, dan triwulan."]},"screens":{"en":["BUMN reports","Report verification","Attachment viewer"],"id":["Laporan BUMN","Verifikasi laporan","Penampil lampiran"]},"sketch":"table"},{"id":"simanis","pdf":"/porto/simanis.pdf","dom":"work","y":320,"live":true,"year":"2023","ongoing":true,"name":"Simanis","runtime":["laravel@5.5.50","php@7.1.26","postgresql"],"org":"Kementerian BUMN","role":{"en":"Maintainer & feature developer","id":"Maintainer & pengembang fitur"},"domain":{"en":"Workforce management","id":"Manajemen kepegawaian"},"sum":{"en":"The ministry''s personnel system, and the oldest codebase I look after — Laravel 5.5 on PHP 7.1. Travel orders, accountability, and the annual and semiannual performance reviews for every employee.","id":"Sistem kepegawaian kementerian, dan basis kode tertua yang saya pegang — Laravel 5.5 di PHP 7.1. Surat tugas, pertanggungjawaban, serta penilaian kinerja tahunan dan semesteran seluruh pegawai."},"hi":{"en":["Travel orders end to end: administration, nominative cost breakdown, accountability, PDF output.","SKP performance review with a rating distribution chart per work unit.","Approval realisation tracking — who has signed, who has not.","Added features to a legacy stack without triggering a rewrite the ministry did not ask for."],"id":["Surat tugas dari hulu ke hilir: administrasi, rincian nominatif, pertanggungjawaban, keluaran PDF.","Penilaian kinerja SKP dengan grafik distribusi nilai per unit kerja.","Pelacakan realisasi persetujuan — siapa sudah tanda tangan, siapa belum.","Menambah fitur di stack legacy tanpa memicu rewrite yang tidak diminta kementerian."]},"screens":{"en":["Travel order — administration","Travel order — accountability","Travel order — nominative","SKP annual distribution","SKP semiannual distribution","Approval realisation"],"id":["Surat tugas — administrasi","Surat tugas — pertanggungjawaban","Surat tugas — nominatif","Distribusi SKP tahunan","Distribusi SKP semesteran","Realisasi persetujuan"]},"sketch":"curve"},{"id":"simo","pdf":"/porto/simanis-mobile.pdf","dom":"work","y":372,"live":true,"year":"2024","ongoing":true,"name":"Simanis Mobile (SIMO)","runtime":["swift@5","ios","xcode"],"org":"Kementerian BUMN","role":{"en":"iOS developer","id":"iOS developer"},"domain":{"en":"Workforce, in the pocket","id":"Kepegawaian, dalam genggaman"},"sum":{"en":"Simanis in an employee''s hand. Clock in from the office or from wherever work is happening, check remaining leave, find a colleague, scan into a meeting.","id":"Simanis dalam genggaman pegawai. Presensi dari kantor atau dari mana pun pekerjaan berlangsung, cek sisa cuti, cari rekan kerja, pindai QR untuk masuk rapat."},"hi":{"en":["Attendance with map-based location check — the app confirms you are inside the office radius before it lets you clock in.","Home screen carrying today''s shift, clock-in and clock-out times, and accumulated lateness.","Directory of every state-owned enterprise with drill-down into commissioners and directors.","Leave balance, meeting QR, calendar and birthdays in one tab bar."],"id":["Presensi dengan pemeriksaan lokasi berbasis peta — aplikasi memastikan Anda di dalam radius kantor sebelum bisa presensi.","Layar utama memuat shift hari ini, jam masuk dan pulang, serta akumulasi keterlambatan.","Direktori seluruh BUMN dengan drill-down ke komisaris dan direksi.","Sisa cuti, QR rapat, kalender, dan ulang tahun dalam satu tab bar."]},"screens":{"en":["Dashboard","Attendance & geofence","BUMN search","BUMN detail"],"id":["Dashboard","Presensi & geofence","Pencarian BUMN","Detail BUMN"]},"sketch":"phone"},{"id":"kuffa","pdf":"/porto/kuffa.pdf","dom":"comm","y":459,"live":false,"year":"2022","name":"Kuffa","runtime":["django@3.1","python@3.9","midtrans"],"org":"STMIK Jayakarta","role":{"en":"Sole developer — final thesis","id":"Pengembang tunggal — tugas akhir"},"domain":{"en":"Fashion e-commerce","id":"E-commerce fesyen"},"sum":{"en":"My thesis, and the one project here you can open and read. A working fashion store — catalogue, cart, checkout, and real money moving through Midtrans. Every credential is read from the environment, none committed.","id":"Tugas akhir saya, dan satu-satunya proyek di sini yang bisa Anda buka dan baca. Toko fesyen yang benar-benar jalan — katalog, keranjang, checkout, dan uang sungguhan lewat Midtrans. Semua kredensial dibaca dari environment, tidak ada yang ikut ter-commit."},"hi":{"en":["Midtrans Snap checkout covering QRIS, bank virtual accounts and cards.","Order confirmation emails dispatched over SMTP once payment settles.","Catalogue and cart modelled with the Django ORM.","The project that turned coursework into something I could hand to a stranger."],"id":["Checkout Midtrans Snap mencakup QRIS, virtual account bank, dan kartu.","Email konfirmasi pesanan dikirim lewat SMTP begitu pembayaran lunas.","Katalog dan keranjang dimodelkan dengan Django ORM.","Proyek yang mengubah tugas kuliah menjadi sesuatu yang bisa saya serahkan ke orang yang belum saya kenal."]},"screens":{"en":["Landing","Catalogue","Product detail","Midtrans checkout"],"id":["Beranda","Katalog","Detail produk","Checkout Midtrans"]},"sketch":"grid","repo":"https://github.com/randysetiawanh/ecommerce-django"}]', 1786000300);
